mapper.select:
SELECT a.`device_code` `deviceCode`, a.`statistical_flag` `statisticalFlag`, a.`code` `code`, a.`shift_master` `shiftMaster`, a.`gear_position_code` `gearPositionCode`, a.`department` `departmentName`, a.`gear_position_area` `gearPositionArea`, a.`unit_traffic` `unitTraffic`, a.`duration` `duration`, a.`flow` `flow`, a.`unit_price` `unitPrice`, a.`total` `total` FROM `water_data_day` a where 1=1
and a.`data_time` between #{param.startTime} and #{param.endTime}
and a.`department_id` like concat('%',#{param.departmentId},'%')
and a.`shift_master` like concat('%',#{param.shiftMaster},'%')
and a.`code` like concat('%',#{param.code},'%')
and a.`device_code` like concat('%',#{param.deviceCode},'%')
and a.`gear_position_code` like concat('%',#{param.gearPositionCode},'%')
and a.`duration` between #{param.duration.startDuration} and #{param.duration.endDuration}
and a.`flow` between #{param.flowParam.startFlow} and #{param.flowParam.endFlow}

select a.`deviceCode`,a.`departmentName`,a.`code`,a.`duration`,a.`flow`,a.`gearPositionArea`,a.`gearPositionCode`,a.`shiftMaster`,a.`total`,a.`unitPrice`,a.`unitTraffic` from ( SELECT `device_code` `deviceCode`, `code` `code`, `shift_master` `shiftMaster`, `gear_position_code` `gearPositionCode`, `department` `departmentName`, `gear_position_area` `gearPositionArea`, `unit_traffic` `unitTraffic`, SUM(`duration`) `duration`, SUM(`flow`) `flow`, `unit_price` `unitPrice`, SUM(`total`) `total` FROM `water_data_day`
and `data_time` between #{param.startTime} and #{param.endTime}
and `department_id` like concat('%',#{param.departmentId},'%')
and `shift_master` like concat('%',#{param.shiftMaster},'%')
and `code` like concat('%',#{param.code},'%')
and `device_code` like concat('%',#{param.deviceCode},'%')
and `gear_position_code` like concat('%',#{param.gearPositionCode},'%')
GROUP BY `device_code`) a
and a.`duration` between #{param.duration.startDuration} and #{param.duration.endDuration}
and a.`flow` between #{param.flowParam.startFlow} and #{param.flowParam.endFlow}

