and a.`flow` between #{param.flowParam.startFlow} and #{param.flowParam.endFlow}

SELECT COALESCE(sum( a.`total` ),0) `total`, COALESCE(sum( a.`duration` ),0) `duration`, COALESCE(sum( a.`flow` ),0) `flow`
FROM `water_data_day` a where 1=1
and a.`data_time` between #{param.startTime} and #{param.endTime}
and a.`department_id` like concat('%',#{param.departmentId},'%')
and a.`shift_master` like concat('%',#{param.shiftMaster},'%')
and a.`code` like concat('%',#{param.code},'%')
and a.`device_code` like concat('%',#{param.deviceCode},'%')
and a.`gear_position_code` like concat('%',#{param.gearPositionCode},'%')
and a.`duration` between #{param.duration.startDuration} and #{param.duration.endDuration}
and a.`flow` between #{param.flowParam.startFlow} and #{param.flowParam.endFlow}

SELECT a.`data_time` `dataTime`, COALESCE(sum( a.`total` ),0) `total`, COALESCE(sum( a.`duration` ),0) `duration`, COALESCE(sum( a.`flow` ),0) `flow` FROM `water_data_day` a where 1=1
and a.`data_time` between #{startTime} and #{endTime}
and a.`device_code` = #{deviceCode}

SELECT `temp`.* FROM ( SELECT t1.`device_code`, CONCAT( YEAR ( t1.`data_time` ), '-', LPAD( MONTH ( t1.`data_time` ), 2, '0' ) ) AS `data_time`, COALESCE(SUM( t1.`flow`), 0) AS `flow`, COALESCE(SUM( t1.`duration`), 0) AS `duration`, COALESCE(SUM( t1.`total`), 0) AS `total` FROM `water_data_day` AS t1 GROUP BY YEAR ( t1.`data_time` ), MONTH ( t1.`data_time` ) ) `temp`
`temp`.`data_time` IN
#{dateTime}
